import sys, json
# Count tool uses by name
counts = {}
writes = []
reads = []
for i, line in enumerate(sys.stdin):
    line=line.strip()
    if not line: continue
    try:
        d=json.loads(line)
        msg = d.get('message',{})
        content = msg.get('content','')
        if isinstance(content, list):
            for c in content:
                if c.get('type')=='tool_use':
                    n = c.get('name','?')
                    counts[n] = counts.get(n,0)+1
                    if n=='Write':
                        writes.append(c.get('input',{}).get('content',''))
                    if n=='Read' and c.get('input',{}).get('file_path','')=='/workspace/answer.txt':
                        reads.append('answer.txt')
    except: pass
print('Tool use counts:', counts)
print('Total Write calls:', len(writes))
print('Distinct Write contents:')
from collections import Counter
for c, n in Counter(writes).most_common():
    print(f'  {n}x: {c!r}')
print('Reads of answer.txt:', len(reads))
"', 'description': 'Summarize tool-use frequencies'}

